        panel("Two levels of urban experience", "comparison-table", ["ANOMIE -> weakened bonds and shared norms under density and anonymity", "CONTINUUM -> continuing village linkage through migration and remittance", "LEVEL -> social-psychological against structural and economic", "RULE -> both can hold for the same household at the same time"], ["Alienation and anomie", "Anomie beside the rural-urban continuum"]),
        panel("Two justice tests", "comparison", ["DISTRIBUTIVE -> are services and infrastructure fairly shared", "PROCEDURAL -> did affected residents have a real planning voice", "SEQUENCE -> exclusion from process usually precedes exclusion from benefit", "USE -> apply both before judging any urban investment"], ["Distributive and procedural justice"]),
        panel("Smart-city design contrast", "matrix", ["EXCLUSIONARY -> upgrading concentrated in designated or better-off zones", "INCLUSIVE -> services, tenure and connectivity extended into settlements", "TEST -> did access change for the informally settled poor", "LIMIT -> technology is an instrument, never a distributive outcome"], ["The smart city under a social lens", "Two smart-city designs"]),
