        panel("Causal restraint on crime", "decision-tree", ["DENSITY ALONE -> insufficient as an explanation of urban crime", "CONFOUNDERS -> inequality, policing, opportunity, reporting, networks", "REQUIREMENT -> context-specific evidence before any causal claim", "SAFE MOVE -> describe mechanisms, refuse an anomie shortcut"], ["Density, crime and the measurement boundary"]),
        panel("Growth and its cost", "path-consequence", ["CLUSTERING -> productivity, matching and a wage premium", "SAME MECHANISM -> congestion, housing-cost inflation, service strain", "TIER-2 -> new middle class, organised retail, consumption aspiration", "READING -> differentiated work and housing, not shared prosperity"], ["Trade-offs, consumption and the answer spine"]),
